WITH cleaned AS (SELECT id, device_code, humidity, pressure, status_bits, firmware, status_bits * humidity AS status_bits_times_humidity FROM device_readings WHERE reading_ts > TIMESTAMP '2025-09-01 10:00:00') SELECT *, COUNT(status_bits) OVER (PARTITION BY device_code) AS device_code_count_status_bits, LEAD(pressure, 1) OVER (PARTITION BY device_code ORDER BY status_bits ASC, id ASC) AS next_pressure FROM cleaned;
